import 'package:dio/dio.dart';
import 'package:flutter/material.dart';
import 'package:flutter_core/flutter_core.dart';
import 'package:flutter_design_system/flutter_design_system.dart';
import 'package:flutter_networking/flutter_networking.dart';
import 'package:go_router/go_router.dart';

const previewMode = String.fromEnvironment('APP_ENV', defaultValue: 'development') != 'production';
final transportProvider = Provider((ref) => createTransport(SecureTokenStore()));
final router = GoRouter(initialLocation: '/login', routes: [
  ShellRoute(builder: (context, state, child) => PilotShell(path: state.uri.path, child: child), routes: [
    GoRoute(path: '/login', builder: (_, __) => const PilotLoginScreen()),
    GoRoute(path: '/dashboard', builder: (_, __) => const PilotDashboardScreen()),
    GoRoute(path: '/requests', builder: (_, __) => const PilotRequestScreen()),
    GoRoute(path: '/pickup', builder: (_, __) => const PickupVerificationScreen()),
    GoRoute(path: '/routes', builder: (_, __) => const MultiStopScreen()),
    GoRoute(path: '/navigation', builder: (_, __) => const CustomerNavigationScreen()),
    GoRoute(path: '/complete', builder: (_, __) => const CompleteDeliveryScreen()),
    GoRoute(path: '/earnings', builder: (_, __) => const PilotEarningsScreen()),
    GoRoute(path: '/profile', builder: (_, __) => const PilotProfileScreen()),
  ]),
]);
void main() => runApp(ProviderScope(child: QuickbuddyApp(title: 'Quickbuddy Pilot', theme: quickbuddyTheme(), router: router)));

class PilotShell extends StatelessWidget {
  const PilotShell({super.key, required this.path, required this.child});
  final String path; final Widget child;
  @override
  Widget build(BuildContext context) {
    final login = path == '/login';
    final selected = path == '/earnings' ? 3 : path == '/profile' ? 4 : path == '/requests' || path == '/pickup' || path == '/complete' ? 1 : path == '/routes' || path == '/navigation' ? 2 : 0;
    return Scaffold(body: SafeArea(child: child), bottomNavigationBar: login ? null : NavigationBar(
      height: 64, selectedIndex: selected, backgroundColor: Colors.white,
      indicatorColor: QuickbuddyColors.orange.withValues(alpha: .1),
      onDestinationSelected: (i) => context.go(switch(i){1=>'/requests',2=>'/routes',3=>'/earnings',4=>'/profile',_=>'/dashboard'}),
      destinations: const [NavigationDestination(icon:Icon(Icons.home_outlined),label:'Home'),NavigationDestination(icon:Icon(Icons.receipt_long_outlined),label:'Orders'),NavigationDestination(icon:Icon(Icons.map_outlined),label:'Map'),NavigationDestination(icon:Icon(Icons.account_balance_wallet_outlined),label:'Earnings'),NavigationDestination(icon:Icon(Icons.person_outline),label:'Profile')],
    ));
  }
}

class PilotLoginScreen extends ConsumerStatefulWidget { const PilotLoginScreen({super.key}); @override ConsumerState<PilotLoginScreen> createState()=>_PilotLoginScreenState(); }
class _PilotLoginScreenState extends ConsumerState<PilotLoginScreen> {
  bool busy=false;
  Future<void> _goOnline() async {
    setState(()=>busy=true);
    try { await ref.read(transportProvider).post('/api/v1/pilots/me/availability',data:{'state':'online_available'}); if(mounted)context.go('/dashboard'); }
    on DioException catch(e) { if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(e.response?.statusCode==401?'Sign in is required before you can go online.':'Availability service is unavailable.'))); }
    finally { if(mounted)setState(()=>busy=false); }
  }
  @override
  Widget build(BuildContext context) => ListView(padding:const EdgeInsets.fromLTRB(18,18,18,24),children:[
    const Center(child:QbBrand(pilot:true)), const SizedBox(height:16),
    ClipRRect(borderRadius:BorderRadius.circular(21),child:Stack(alignment:Alignment.bottomLeft,children:[QbPhoto('rider',height:300,width:double.infinity),Container(height:300,decoration:const BoxDecoration(gradient:LinearGradient(begin:Alignment.topCenter,end:Alignment.bottomCenter,colors:[Colors.transparent,Color(0xD9101727)]))),const Padding(padding:EdgeInsets.all(17),child:Text('More deliveries.\nBigger opportunities.',style:TextStyle(color:Colors.white,fontSize:24,fontWeight:FontWeight.w800,height:1.15)))])),
    const SizedBox(height:16),const Text('Delivering opportunities, a brighter tomorrow',textAlign:TextAlign.center,style:TextStyle(color:QuickbuddyColors.indigo,fontSize:18,fontWeight:FontWeight.w800)),
    const SizedBox(height:10),if(previewMode)const QbPreviewNotice(message:'Pilot sign-in and eligibility checks require a configured identity provider.'),
    const SizedBox(height:12),const _PerkRow(icon:Icons.schedule,title:'Flexible hours'),const _PerkRow(icon:Icons.payments_outlined,title:'Clear earnings'),const _PerkRow(icon:Icons.health_and_safety_outlined,title:'Safety and support'),
    const SizedBox(height:12),QbPrimaryButton(label:busy?'Connecting…':'Go online',icon:Icons.bolt,onPressed:busy?null:_goOnline),
    const SizedBox(height:7),OutlinedButton.icon(onPressed:()=>_showAuthInfo(context),icon:const Icon(Icons.phone_android),label:const Text('Login with phone')),
  ]);
}

